  void _handleLogin() {
    if (_formKey.currentState?.validate() ?? false) {
      setState(() => _isLoading = true);
      Future.delayed(const Duration(milliseconds: 600), () {
        if (!mounted) return;
        final email = _emailController.text.trim().toLowerCase();

        // El sistema detecta automáticamente si es cuidador o cliente
        final bool isCaregiver = email.contains('cuidador') ||
            email == 'claudia.morales@cuidarte.org';
        final UserRole detectedRole = isCaregiver ? UserRole.caregiver : UserRole.client;

        final auth = context.read<AuthProvider>();
        auth.login(
          email: _emailController.text,
          password: _passwordController.text,
          role: detectedRole,
        );
        setState(() => _isLoading = false);

        if (detectedRole == UserRole.caregiver) {
          Navigator.of(context).pushReplacement(
            MaterialPageRoute(builder: (_) => const CaregiverDashboardScreen()),
          );
        } else {
          Navigator.of(context).pushReplacement(
            MaterialPageRoute(builder: (_) => const MainNavigationScreen()),
          );
