   ESTILOS PARA SELECCIÓN DE TIPO DE USUARIO
   ======================================== */

.seleccion-hero {
  min-height: calc(100vh - 80px);
  background: linear-gradient(135deg, #27BEF5 0%, #6DD5FA 50%, #27BEF5 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
}

.seleccion-container {
  max-width: 1200px;
  width: 100%;
}

.seleccion-header {
  text-align: center;
  margin-bottom: 50px;
  color: white;
}

.seleccion-header h1 {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 15px;
}

.seleccion-header p {
  font-size: 1.1rem;
  opacity: 0.95;
}

.tipos-container {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 30px;
  margin-bottom: 40px;
}

.tipo-card {
  background: white;
  border-radius: 20px;
  padding: 40px 30px;
  text-decoration: none;
  color: #2d2d2d;
  transition: all 0.4s ease;
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 40px rgba(0,0,0,0.15);
  position: relative;
  overflow: hidden;
}

.tipo-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 5px;
  background: linear-gradient(90deg, #27BEF5, #6DD5FA);
  transform: scaleX(0);
  transition: transform 0.4s ease;
}

.tipo-card:hover {
  transform: translateY(-10px);
  box-shadow: 0 20px 60px rgba(0,0,0,0.25);
}

.tipo-card:hover::before {
  transform: scaleX(1);
}

.tipo-icon {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, #e3f8ff, #b3e5fc);
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 25px;
  color: #27BEF5;
}

.tipo-icon svg {
  width: 40px;
  height: 40px;
}

.tipo-card-cuidador .tipo-icon {
  background: linear-gradient(135deg, #fff3e0, #ffe0b2);
  color: #FF9800;
}

.tipo-card h2 {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 12px;
  color: #2d2d2d;
}

.tipo-card p {
  color: #6b7280;
  font-size: 0.95rem;
  margin-bottom: 25px;
  line-height: 1.6;
}

.tipo-beneficios {
  list-style: none;
  padding: 0;
  margin: 0 0 30px 0;
  flex-grow: 1;
}

.tipo-beneficios li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  color: #4b5563;
  font-size: 0.9rem;
}

.tipo-beneficios svg {
  width: 20px;
  height: 20px;
  color: #27BEF5;
  flex-shrink: 0;
}

.tipo-card-cuidador .tipo-beneficios svg {
  color: #FF9800;
}

.tipo-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, #27BEF5, #6DD5FA);
  color: white;
  padding: 15px 20px;
  border-radius: 12px;
  font-weight: 600;
  transition: all 0.3s ease;
}

.tipo-card-cuidador .tipo-btn {
  background: linear-gradient(135deg, #FF9800, #FFB74D);
}

.tipo-btn svg {
  width: 20px;
  height: 20px;
  transition: transform 0.3s ease;
}

.tipo-card:hover .tipo-btn svg {
  transform: translateX(5px);
}

.seleccion-footer {
  text-align: center;
  color: white;
  font-size: 0.95rem;
}

.seleccion-footer a {
  color: white;
  text-decoration: underline;
  font-weight: 600;
}

@media (max-width: 968px) {
  .tipos-container {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  
  .seleccion-header h1 {
    font-size: 2rem;
  }
}

