def ingresar(request):
    email = ''
    if request.method == 'POST':
        email = (request.POST.get('email') or request.POST.get('username') or '').strip()
        password = request.POST.get('password')
        user = None
        # Login por correo electrónico (profesional) - busca el username asociado al email
        if email:
            try:
                user_obj = User.objects.get(email__iexact=email)
                user = authenticate(request, username=user_obj.username, password=password)
            except User.DoesNotExist:
                # Fallback: intentar como username por compatibilidad con usuarios antiguos
                user = authenticate(request, username=email, password=password)
        if user is not None:
            login(request, user)
            next_url = request.POST.get('next') or request.GET.get('next')
            if next_url:
                return redirect(next_url)
            # Redirigir según el tipo de usuario
            if user.is_staff or user.is_superuser:
                return redirect('aplicacion:admin_dashboard')
            if hasattr(user, 'perfil'):
                if user.perfil.tipo_usuario == 'cuidador':
                    return redirect('aplicacion:dashboard_cuidador')
                else:
                    return redirect('aplicacion:dashboard_cliente')
            return redirect('aplicacion:dashboard_cliente')
