              children: [
                Container(
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: AppColors.primaryContainer.withOpacity(0.5),
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: const Row(
                    children: [
                      Icon(Icons.info_outline, color: AppColors.primaryDark),
                      SizedBox(width: 12),
                      Expanded(
                        child: Text(
                          'CuidArte te ayuda a encontrar cuidadores verificados para tu ser querido con atención cálida y personalizada.',
                          style: TextStyle(
                            fontSize: 13,
                            color: AppColors.primaryDark,
                            height: 1.35,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 24),
                const Text(
                  'Datos del Adulto Mayor',
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                    color: AppColors.textPrimary,
                  ),
                ),
                const SizedBox(height: 14),
                TextFormField(
                  controller: _nameController,
                  decoration: const InputDecoration(
                    labelText: 'Nombre y Apellidos del Adulto Mayor',
                    prefixIcon: Icon(Icons.elderly_rounded, color: AppColors.primary),
                  ),
                  validator: (val) => val == null || val.isEmpty ? 'Ingresa el nombre completo' : null,
                ),
                const SizedBox(height: 16),
                TextFormField(
                  controller: _conditionController,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Condición médica o nivel de dependencia',
                    hintText: 'Ej. Movilidad reducida, recuperación de cadera, etc.',
                    prefixIcon: Icon(Icons.medical_information_outlined, color: AppColors.primary),
                  ),
                  validator: (val) => val == null || val.isEmpty ? 'Describe brevemente la condición' : null,
                ),
                const SizedBox(height: 24),
                const Text(
                  'Datos del Tutor o Familiar Responsable',
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                    color: AppColors.textPrimary,
                  ),
                ),
                const SizedBox(height: 14),
                TextFormField(
                  controller: _tutorController,
                  decoration: const InputDecoration(
                    labelText: 'Nombre del Familiar / Tutor Principal',
                    prefixIcon: Icon(Icons.person_outline_rounded, color: AppColors.primary),
                  ),
                  validator: (val) => val == null || val.isEmpty ? 'Ingresa el nombre del responsable' : null,
                ),
                const SizedBox(height: 16),
                TextFormField(
                  controller: _phoneController,
                  keyboardType: TextInputType.phone,
                  decoration: const InputDecoration(
                    labelText: 'Teléfono celular de contacto',
                    prefixIcon: Icon(Icons.phone_outlined, color: AppColors.primary),
                  ),
                  validator: (val) => val == null || val.isEmpty ? 'Ingresa el celular' : null,
                ),
                const SizedBox(height: 16),
                TextFormField(
                  controller: _emailController,
                  keyboardType: TextInputType.emailAddress,
                  decoration: const InputDecoration(
                    labelText: 'Correo electrónico',
                    prefixIcon: Icon(Icons.email_outlined, color: AppColors.primary),
                  ),
                  validator: (val) => val == null || !val.contains('@') ? 'Ingresa un correo válido' : null,
                ),
                const SizedBox(height: 16),
                Row(
                  children: [
                    Expanded(
                      flex: 2,
                      child: TextFormField(
                        controller: _cityController,
                        decoration: const InputDecoration(
                          labelText: 'Ciudad',
                          prefixIcon: Icon(Icons.location_city_rounded, color: AppColors.primary),
                        ),
                        validator: (val) => val == null || val.isEmpty ? 'Ciudad' : null,
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      flex: 3,
                      child: TextFormField(
                        controller: _addressController,
                        decoration: const InputDecoration(
                          labelText: 'Dirección domicilio',
                          prefixIcon: Icon(Icons.home_outlined, color: AppColors.primary),
                        ),
                        validator: (val) => val == null || val.isEmpty ? 'Dirección' : null,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 32),
                CustomButton(
                  text: 'Completar Registro Familiar',
                  isLoading: _isLoading,
                  onPressed: _handleSubmit,
                ),
                const SizedBox(height: 24),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

