    required this.address,
    required this.role,
    this.tutorName,
    this.elderlyCondition,
    this.avatarUrl,
    this.cedula,
    this.experienceYears,
  });

  UserModel copyWith({
    String? id,
    String? name,
    String? email,
    String? phone,
    String? city,
    String? address,
    UserRole? role,
    String? tutorName,
    String? elderlyCondition,
    String? avatarUrl,
