  color: #9ca3af;
}

/* Password Strength Indicator */
.password-strength {
  margin-top: 8px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.strength-bar {
  flex: 1;
  height: 6px;
  background: #e5e7eb;
  border-radius: 10px;
  overflow: hidden;
}

.strength-fill {
  height: 100%;
  width: 0%;
  background: #27BEF5;
  border-radius: 10px;
  transition: all 0.3s ease;
}

.strength-text {
  font-size: 0.85rem;
  color: #6b7280;
}

.strength-text strong {
  color: #27BEF5;
}

/* Checkbox */
.form-checkbox {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin: 4px 0;
}

.form-checkbox input[type="checkbox"] {
  width: 18px;
  height: 18px;
  cursor: pointer;
  flex-shrink: 0;
  margin-top: 2px;
  accent-color: #27BEF5;
}

.form-checkbox label {
  font-size: 0.85rem;
  color: #6b7280;
  line-height: 1.5;
}

.form-checkbox label a {
  color: #27BEF5;
  text-decoration: none;
  font-weight: 600;
  transition: color 0.3s ease;
}

.form-checkbox label a:hover {
  color: #1BA0D1;
  text-decoration: underline;
}

/* Botón Primary */
.btn-primary {
  background: linear-gradient(135deg, #27BEF5, #6DD5FA);
  color: white;
  padding: 14px;
  border: none;
  border-radius: 12px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 8px 25px rgba(39, 190, 245, 0.3);
  font-family: 'Poppins', sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 4px;
}

.btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 35px rgba(39, 190, 245, 0.4);
}

.btn-primary:active {
  transform: translateY(-1px);
}

.btn-primary svg {
  transition: transform 0.3s ease;
}

.btn-primary:hover svg {
  transform: translateX(5px);
}

/* Divider */
.divider {
  display: flex;
  align-items: center;
  gap: 15px;
  margin: 25px 0;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: #e5e7eb;
}

.divider span {
  color: #6b7280;
  font-size: 0.9rem;
}

/* Social Registro */
.social-registro {
  display: flex;
  gap: 15px;
}

.social-btn {
  flex: 1;
  padding: 12px;
  border: 2px solid #e5e7eb;
  border-radius: 12px;
  background: white;
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-weight: 500;
  font-family: 'Poppins', sans-serif;
}

.social-btn:hover {
  border-color: #27BEF5;
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(0,0,0,0.1);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

/* Login Link */
.login-link {
  text-align: center;
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid #e5e7eb;
}

.login-link p {
  color: #6b7280;
  font-size: 0.875rem;
}

.login-link a {
  color: #27BEF5;
  text-decoration: none;
  font-weight: 600;
  transition: color 0.3s ease;
}

.login-link a:hover {
  color: #1BA0D1;
  text-decoration: underline;
}

/* Mensajes de error y éxito */
.error-messages {
  background: linear-gradient(135deg, #fee, #fdd);
  border: 2px solid #fcc;
  border-left: 5px solid #e74c3c;
  padding: 12px 15px;
  border-radius: 10px;
  margin-bottom: 15px;
  animation: slideDown 0.4s ease;
  position: relative;
  z-index: 10;
}

.error-messages p {
  color: #c33;
  margin: 3px 0;
  font-size: 0.8rem;
  font-weight: 500;
  line-height: 1.4;
}

.success-messages {
  background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
  border: 2px solid #a5d6a7;
  border-left: 5px solid #4caf50;
  padding: 15px 18px;
  border-radius: 12px;
  margin-bottom: 20px;
  animation: slideDown 0.4s ease;
}

.success-messages p {
  color: #2e7d32;
  margin: 5px 0;
  font-size: 0.875rem;
  font-weight: 500;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

