      decoration: const BoxDecoration(gradient: AppColors.heroGradient),
      child: Stack(
        children: [
          Positioned(
            top: -200,
            right: -100,
            child: _Bubble(size: 500),
          ),
          Positioned(
            bottom: -100,
            left: -50,
            child: _Bubble(size: 300),
          ),
          SafeArea(child: child),
        ],
      ),
    );
  }
}

class _Bubble extends StatelessWidget {
  final double size;

  const _Bubble({required this.size});

  @override
