import 'package:flutter/material.dart';
import '../models/user_model.dart';
import '../models/user_role.dart';
import '../data/mock_data.dart';

class AuthProvider with ChangeNotifier {
  UserModel? _currentUser;
  bool _isAuthenticated = true;

  /// Cuentas de cuidador conocidas. En Django el rol se resuelve consultando
  /// el perfil del usuario; aquí simulamos esa misma resolución.
  final Set<String> _caregiverEmails = {
    MockData.sampleCaregiverUser.email.toLowerCase(),
    ...MockData.caregivers.map((caregiver) => caregiver.email.toLowerCase()),
  };

  AuthProvider() {
    _currentUser = MockData.sampleClient;
  }

  UserModel? get currentUser => _currentUser;
  bool get isAuthenticated => _isAuthenticated;
  UserRole get currentRole => _currentUser?.role ?? UserRole.client;
  bool get isCaregiver => currentRole == UserRole.caregiver;
  bool get isClient => currentRole == UserRole.client;

  UserRole detectRole(String email) {
    final normalized = email.trim().toLowerCase();
    if (_caregiverEmails.contains(normalized) || normalized.contains('cuidador')) {
      return UserRole.caregiver;
    }
    return UserRole.client;
  }

  /// Inicia sesión y devuelve el rol detectado automáticamente.
  UserRole loginAutoDetect({
    required String email,
    required String password,
  }) {
    final role = detectRole(email);
    _currentUser = role == UserRole.caregiver
        ? MockData.sampleCaregiverUser.copyWith(email: email.trim())
        : MockData.sampleClient.copyWith(email: email.trim());
    _isAuthenticated = true;
    notifyListeners();
    return role;
  }

  void switchRole(UserRole role) {
    _currentUser = role == UserRole.client
        ? MockData.sampleClient
        : MockData.sampleCaregiverUser;
    notifyListeners();
  }

  void registerClientAccount({
    required String name,
    required String lastName,
    required String email,
    required DateTime birthDate,
    required String password,
  }) {
    _currentUser = UserModel(
      id: 'usr_${DateTime.now().millisecondsSinceEpoch}',
      name: '$name $lastName'.trim(),
      email: email.trim(),
      phone: '',
      city: '',
      address: '',
      role: UserRole.client,
      tutorName: '$name $lastName'.trim(),
      elderlyCondition: '',
      avatarUrl:
          'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=300&auto=format&fit=crop&q=80',
    );
    _isAuthenticated = true;
    notifyListeners();
  }

  void registerCaregiverAccount({
    required String name,
    required String lastName,
    required String email,
    required String phone,
    required DateTime birthDate,
    required String specialty,
    required String experience,
    required String password,
  }) {
    _currentUser = UserModel(
      id: 'cg_${DateTime.now().millisecondsSinceEpoch}',
      name: '$name $lastName'.trim(),
      email: email.trim(),
      phone: phone.trim(),
      city: '',
      address: '',
      role: UserRole.caregiver,
      experienceYears: 0,
      avatarUrl:
          'https://images.unsplash.com/photo-1594824813689-d9735d492473?w=300&auto=format&fit=crop&q=80',
    );
    _caregiverEmails.add(email.trim().toLowerCase());
    _isAuthenticated = true;
    notifyListeners();
  }

  void logout() {
    _isAuthenticated = false;
    notifyListeners();
  }
}

