import 'package:cuidarte_app/providers/visit_provider.dart';
import 'package:cuidarte_app/providers/workshop_provider.dart';
import 'package:cuidarte_app/data/mock_data.dart';

void main() {
  group('CuidArte Core Logic & Providers Tests', () {
    test('AuthProvider initializes with sample client and switches roles smoothly', () {
      final auth = AuthProvider();
      expect(auth.isAuthenticated, isTrue);
      expect(auth.currentRole, UserRole.client);
      expect(auth.currentUser?.name, 'Carlos Mendoza');

      auth.switchRole(UserRole.caregiver);
      expect(auth.currentRole, UserRole.caregiver);
      expect(auth.isCaregiver, isTrue);
      expect(auth.currentUser?.name, 'Lic. Claudia Morales');
    });

    test('CaregiverProvider filters correctly by city and query', () {
      final caregiverProv = CaregiverProvider();
      expect(caregiverProv.caregivers.isNotEmpty, isTrue);

      caregiverProv.setCity('Medellín');
      expect(caregiverProv.filteredCaregivers.every((c) => c.city == 'Medellín'), isTrue);

      caregiverProv.resetFilters();
      caregiverProv.setSearchQuery('Alzheimer');
      expect(caregiverProv.filteredCaregivers.isNotEmpty, isTrue);
    });

    test('ShopProvider handles cart operations, subtotals and checkout', () {
      final shop = ShopProvider();
      expect(shop.cartCount, 0);

      final product = MockData.products.first;
      shop.addToCart(product);
      expect(shop.cartCount, 1);
      expect(shop.subtotal, product.price);

      shop.updateQuantity(product.id, 2);
      expect(shop.cartCount, 2);
      expect(shop.subtotal, product.price * 2);

      // Checkout
      final order = shop.checkout(
        recipientName: 'Carlos Mendoza',
        recipientPhone: '+57 312 456 7890',
        shippingAddress: 'Calle 127 # 19-45',
        city: 'Bogotá',
        paymentMethod: 'Contra entrega',
      );

      expect(order.orderNumber.startsWith('#CU-'), isTrue);
      expect(order.qrCodeData.contains('CUIDARTE-VERIFIED-INVOICE'), isTrue);
      expect(shop.cartCount, 0);
      expect(shop.orders.length, 1);
    });

    test('VisitProvider schedules free initial diagnostic visit', () {
      final visitProv = VisitProvider();
      final initialCount = visitProv.visits.length;

      final caregiver = MockData.caregivers.first;
      final client = MockData.sampleClient;

      final scheduled = visitProv.scheduleVisit(
        caregiver: caregiver,
        client: client,
        date: DateTime.now().add(const Duration(days: 2)),
        timeSlot: '10:00 AM - 11:30 AM',
        notes: 'Primera valoración',
      );

      expect(scheduled.isFreeInitialVisit, isTrue);
      expect(scheduled.status, 'Pendiente');

